export PATH="$HOME/.bun/bin:$PATH"; gbrain setup claude-code --json > /tmp/gbrain-doc/setup.json 2>/tmp/gbrain-doc/setup.err; echo rc=$?; cat /tmp/gbrain-doc/setup.err; python3 -I -c '
import json,sys; d=json.load(open(sys.argv[1]))
print("state:",d.get("state")); print("verify:",json.dumps(d.get("verify"),indent=1)[:1500])
for n in d.get("notices",[]):
  print("NOTICE",n.get("code"),n.get("kind")); print(" ",n.get("user_message"))
  for dec in n.get("decisions",[]): print("  -",dec["id"],"default=",dec.get("default"),"|",dec.get("default_reason"))
' /tmp/gbrain-doc/setup.json

cd /tmp && node -e '
const d=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8"));
console.log("state:",JSON.stringify(d.state));console.log("verify:",JSON.stringify(d.verify,null,1).slice(0,2000));
console.log("instructions:",JSON.stringify(d.instructions));
for(const n of d.notices||[]){console.log("NOTICE",n.code,n.kind,"\n ",n.user_message);for(const x of n.decisions||[])console.log("  -",x.id,"default=",x.default,"|",x.default_reason||"")}
' /tmp/gbrain-doc/setup.json; cat /harness-state/claude/settings.json

